90	import { createAuraApp, sceneKits } from "@aura3d/engine";
91	
92	const kit = sceneKits.materialLab();
93	export const app = createAuraApp("#stage", kit.toAppOptions());
94	export const problems = kit.diagnostics.problems;
95	```
